cket. is it powered on? flashLed(errorLed, 3, 500); } } } else if (xbee.getResponse().isError()) { //nss.print("Error reading packet. Error code: "); //nss.println(xbee.getResponse().getErrorCode()); } else { // local XBee did not provide a timely TX Status Response -- should not happen flashLed(errorLed, 1, 50); } } delay(2000); }
